<section class="auth-card"><p class="eyebrow">Start selling in minutes</p><h1>Create your merchant account</h1><p class="muted">Your storefront setup comes next.</p><form method="post" action="/register" class="form-stack" novalidate><?= csrf_field() ?><label>Full name<input name="name" value="<?= e(old('name')) ?>" required minlength="2" maxlength="100" autocomplete="name"></label><label>Email<input type="email" name="email" value="<?= e(old('email')) ?>" required maxlength="190" autocomplete="email"></label><label>Password<input type="password" name="password" required minlength="12" autocomplete="new-password"><small>At least 12 characters with uppercase, lowercase, and a number.</small></label><label>Confirm password<input type="password" name="password_confirmation" required autocomplete="new-password"></label><button class="button primary" type="submit">Create account</button></form><p class="switch">Already registered? <a href="/login">Sign in</a></p></section>
